from .repository import existing_emails, put_contact

_CONTACT_FIELDS = frozenset({"email", "name"})

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _parse_row(index, row):
    if not isinstance(row, dict):
        raise ValueError(f"row {index} must be an object")
    fields = set(row)
    missing = _CONTACT_FIELDS - fields
    if missing:
        raise ValueError(f"row {index} is missing fields: {sorted(missing)}")
    unknown = fields - _CONTACT_FIELDS
    if unknown:
        raise ValueError(f"row {index} has unknown fields: {sorted(map(repr, unknown))}")
    email, name = row["email"], row["name"]
    if not isinstance(email, str) or not isinstance(name, str):
        raise ValueError(f"row {index} email and name must be strings")
    email = email.strip()
    name = name.strip()
    if email.count("@") != 1:
        raise ValueError(f"row {index} email must contain exactly one '@'")
    local, domain = email.split("@")
    if not local or not domain or any(ch.isspace() for ch in email):
        raise ValueError(f"row {index} email is malformed")
    if not name:
        raise ValueError(f"row {index} name must not be empty")
    return email.lower(), name

def import_contacts(connection, rows):
    if not isinstance(rows, list):
        raise ValueError("rows must be a list")
    batch = {}
    for index, row in enumerate(rows):
        email, name = _parse_row(index, row)
        if email in batch:
            raise ValueError(f"duplicate email in batch: {email}")
        batch[email] = name
    if not batch:
        return {"inserted": 0, "updated": 0}
    with connection:
        connection.execute("BEGIN IMMEDIATE")
        updated = len(existing_emails(connection, batch))
        for email, name in batch.items():
            put_contact(connection, email, name)
    return {"inserted": len(batch) - updated, "updated": updated}
